-- rowfence 0.1.0-dev: trees_in_batches. Generated by rowfence migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowfence makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '3d07d9085028119d', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '3d07d9085028119d' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '3d07d9085028119d' THEN
    RAISE EXCEPTION 'rowfence: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_attribute
             WHERE attrelid = to_regclass('authz.policy_versions') AND attname = 'lock' AND NOT attisdropped) THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock IS DISTINCT FROM '51c8991ce738e800' THEN
    RAISE EXCEPTION 'rowfence: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '51c8991ce738e800', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowfence push or apply since needs the '
                   'migrations from the start (or rowfence apply of the policy the previous migration left)';
  END IF;
END $authz_guard$;

-- trees built beside the ones in use (by the migration before) take their place
CREATE SCHEMA IF NOT EXISTS authz_keep;
ALTER TABLE authz_int."group__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."group__parent__tree__next" RENAME TO "group__parent__tree";
DO $authz_swap$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.relname FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid
           WHERE i.indrelid = to_regclass('authz_keep."group__parent__tree"') LOOP
    EXECUTE format('ALTER INDEX authz_keep.%I RENAME TO %I', r.relname,
                   replace(r.relname, 'group__parent__tree__next', 'group__parent__tree'));
  END LOOP;
END $authz_swap$;
ALTER TABLE authz_int."folder__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."folder__parent__tree__next" RENAME TO "folder__parent__tree";
DO $authz_swap$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.relname FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid = i.indexrelid
           WHERE i.indrelid = to_regclass('authz_keep."folder__parent__tree"') LOOP
    EXECUTE format('ALTER INDEX authz_keep.%I RENAME TO %I', r.relname,
                   replace(r.relname, 'folder__parent__tree__next', 'folder__parent__tree'));
  END LOOP;
END $authz_swap$;

-- the triggers rebuilt trees made on tables their conditions read
DO $authz_dyn$
DECLARE r record;
BEGIN
  FOR r IN SELECT t.tgname, t.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger t
           WHERE t.tgname = ANY (ARRAY['authz_folder__parent__tree_dep', 'authz_group__parent__tree_dep']) LOOP
    EXECUTE format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_dyn$;

-- views that change stay where they are, emptied (the same columns, reading nothing) while what they
-- read is dropped and made again; they are defined again below. What the app built on one stays
DO $authz_stub$
DECLARE v text; cols text;
BEGIN
  FOREACH v IN ARRAY ARRAY['authz_int."folder__edit"', 'authz_int."folder__share"', 'authz_int."folder__view"', 'authz_int."group__manage"'] LOOP
    CONTINUE WHEN pg_catalog.to_regclass(v) IS NULL;
    SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = pg_catalog.to_regclass(v) AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
    EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v, cols);
  END LOOP;
END $authz_stub$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_del" ON "fm"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_ins" ON "fm"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_trunc" ON "fm"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_upd" ON "fm"."folders";
DROP TRIGGER IF EXISTS "authz_group__parent__tree_del" ON "fm"."groups";
DROP TRIGGER IF EXISTS "authz_group__parent__tree_ins" ON "fm"."groups";
DROP TRIGGER IF EXISTS "authz_group__parent__tree_trunc" ON "fm"."groups";
DROP TRIGGER IF EXISTS "authz_group__parent__tree_upd" ON "fm"."groups";
DROP VIEW IF EXISTS
  authz_int."folder__parent__tree_conds",
  authz_int."folder__parent__tree_links",
  authz_int."folder__parent__tree_parents",
  authz_int."group__parent__tree_links",
  authz_int."group__parent__tree_parents";
DROP FUNCTION IF EXISTS
  authz_int."folder__parent__tree__next_compute"(p_ids bigint[]),
  authz_int."folder__parent__tree_check_loops"(p_ids bigint[]),
  authz_int."folder__parent__tree_compute"(p_ids bigint[]),
  authz_int."folder__parent__tree_on_rows"(),
  authz_int."folder__parent__tree_on_truncate"(),
  authz_int."folder__parent__tree_rebuild"(),
  authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean),
  authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]),
  authz_int."folder__parent__tree_verify"(),
  authz_int."group__parent__tree__next_compute"(p_ids uuid[]),
  authz_int."group__parent__tree_check_loops"(p_ids uuid[]),
  authz_int."group__parent__tree_compute"(p_ids uuid[]),
  authz_int."group__parent__tree_on_rows"(),
  authz_int."group__parent__tree_on_truncate"(),
  authz_int."group__parent__tree_rebuild"(),
  authz_int."group__parent__tree_refresh"(p_ids uuid[], p_shift boolean),
  authz_int."group__parent__tree_shift"(p_ids uuid[], p_below uuid[]),
  authz_int."group__parent__tree_verify"();
DROP TABLE IF EXISTS
  authz_int."folder__parent__tree",
  authz_int."folder__parent__tree__next",
  authz_int."group__parent__tree",
  authz_int."group__parent__tree__next";

-- rebuilt inheritance trees start empty
CREATE TEMP TABLE IF NOT EXISTS authz_kept (name text PRIMARY KEY) ON COMMIT DROP;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowfence''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- authz_int.trees: its rows again
DELETE FROM authz_int.trees;
INSERT INTO authz_int.trees VALUES
  ('group__parent__tree', '7234bd29660f6bacdc6d6986adddd20e', ARRAY[to_regclass('"fm"."groups"')::oid]::oid[]),
  ('folder__parent__tree', '8e07c42d47425898e0c888c9702ee596', ARRAY[to_regclass('"fm"."folders"')::oid]::oid[]);

-- group: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."group__parent__tree" (descendant uuid NOT NULL, ancestor uuid NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."group__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('group', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."group__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."group__parent__tree";
    ALTER TABLE authz_keep."group__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('group__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."group__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."group__parent__tree_compute"(p_ids uuid[]) RETURNS TABLE (o_descendant uuid, o_ancestor uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."groups" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."groups" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "fm"."groups" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."group__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 9: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."group__parent__tree_shift"(p_ids uuid[], p_below uuid[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched uuid[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."group__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."group__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."groups" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."group__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."group__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."group__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."group__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."group__parent__tree_refresh"(p_ids uuid[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected uuid[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."group__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."group__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('group', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."group__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch uuid[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  DELETE FROM authz_int."group__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."group__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."group__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."group__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch uuid[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."group__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."group__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."group__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."group__parent__tree_check_loops"(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."group__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'group % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowfence help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."group__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids uuid[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."group__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."group__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_group__parent__tree_ins" AFTER INSERT ON "fm"."groups"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_upd" AFTER UPDATE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_del" AFTER DELETE ON "fm"."groups"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_rows"();
CREATE TRIGGER "authz_group__parent__tree_trunc" AFTER TRUNCATE ON "fm"."groups"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."group__parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'group__parent__tree') THEN
    PERFORM authz_int."group__parent__tree_rebuild"();
  END IF;
END $b$;

-- group__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'group__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'group__parent__tree') THEN
    RAISE EXCEPTION 'rowfence: group__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'group' AND '*' = ANY (c.object_ids)
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."group__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."group__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "fm"."groups" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::uuid FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'group' AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."group__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'group__parent__tree';
END $authz_catch_up$;

-- folder: each row with every ancestor it inherits from, through parent while {inherit}
CREATE TABLE authz_int."folder__parent__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  PRIMARY KEY (descendant, ancestor));
CREATE INDEX ON authz_int."folder__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('folder', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder__parent__tree";
    ALTER TABLE authz_keep."folder__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."folder__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder__parent__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "fm"."folders" x WHERE x."id" = ANY (p_ids)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "fm"."folders" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))
      AND EXISTS (SELECT 1 FROM "fm"."folders" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- the conditions on each row (and the type's where)
CREATE VIEW authz_int."folder__parent__tree_conds" AS
  SELECT r."id" AS id, ARRAY[coalesce((inherit), false)] AS v FROM "fm"."folders" r;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN
  CREATE TEMP TABLE authz_probe (LIKE "fm"."folders");
  BEGIN
    CREATE INDEX ON authz_probe ((coalesce((inherit), false)));
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'line 31: a condition that limits inheritance must give the same answer for every user at any time (%) [AZ603]', SQLERRM;
  END;
  DROP TABLE authz_probe;
  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."folder__parent__tree_links"'::regclass, 'authz_int."folder__parent__tree_conds"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION 'line 31: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest(p_below) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE ((e._link = 0 AND coalesce((inherit), false))) AND e._parent = ANY (p_below)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY (p_ids) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest(p_ids) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE ((e._link = 0 AND coalesce((inherit), false))));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest(p_below) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."folders" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest(p_ids) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."folder__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."folder__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."folder__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."folder__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."folder__parent__tree_parents" e WHERE e._child = ANY (p_ids)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'folder % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowfence help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
         OR (SELECT coalesce((inherit), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((inherit), false) FROM (SELECT o.*) r)
      UNION SELECT unnest(ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."folder__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_ins" AFTER INSERT ON "fm"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_upd" AFTER UPDATE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_del" AFTER DELETE ON "fm"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_trunc" AFTER TRUNCATE ON "fm"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_truncate"();

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();
  END IF;
END $b$;

-- folder__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    RAISE EXCEPTION 'rowfence: folder__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'folder' AND '*' = ANY (c.object_ids)
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "fm"."folders" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::bigint FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'folder' AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."folder__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
END $authz_catch_up$;

-- group.manage (line 17): owner or admin or parent.manage
CREATE OR REPLACE VIEW authz_int."group__manage" AS
  SELECT c.descendant AS id FROM authz_int."group__parent__tree" c
  WHERE c.ancestor IN (SELECT authz_int."group__manage__start"());

-- folder.share (line 31): owner or (parent.share and {inherit})
CREATE OR REPLACE VIEW authz_int."folder__share" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT authz_int."folder__share__start"());

-- folder.edit (line 32): share or editor or (parent.edit and {inherit})
CREATE OR REPLACE VIEW authz_int."folder__edit" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT authz_int."folder__edit__start"());

-- folder.view (line 33): edit or viewer or (parent.view and {inherit})
CREATE OR REPLACE VIEW authz_int."folder__view" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT authz_int."folder__view__start"());

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('fm_app');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'fm_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'fm_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'fm_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- rowfence's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'fm_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'fm_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'fm_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'fm_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'fm_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowfence''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relforcerowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"', '"fm"."users"']::text[]) x) LOOP
    IF r.relowner = v_role OR pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      IF NOT r.relforcerowsecurity THEN
        severity := 'error'; object := r.tbl::text;
        problem := format('is owned by %s (or a role it belongs to): owners skip row-level security unless you ALTER TABLE %s FORCE ROW LEVEL SECURITY', 'fm_app', r.tbl);
        RETURN NEXT;
      END IF;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'fm_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'fm_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'fm_app', r.tbl, 'fm_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowfence didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) x)
             AND d.description IS DISTINCT FROM 'authzc'
             AND p.polname NOT IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowfence''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'fm_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowfence''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'fm_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"', '"fm"."users"', '"fm"."group_members"', '"fm"."groups"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"', '"fm"."users"', '"fm"."group_members"', '"fm"."groups"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'fm_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules and the triggers of the table above
  -- (apply turns row-level security on for the ones there are then; later ones are found here)
  FOR r IN WITH RECURSIVE d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i
             JOIN (SELECT to_regclass(t) AS tbl, true AS governed FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) t
                   UNION ALL SELECT to_regclass(t), false FROM unnest(ARRAY[]::text[]) t) x
               ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'fm_app', r.tbl, r.part, 'fm_app');
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE')
                                 OR (r.governed AND has_table_privilege(v_role, r.part, 'SELECT'))) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'fm_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a column it may insert or update, not GENERATED ALWAYS): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'fm_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'fm_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(x) AS tbl FROM unnest(ARRAY[]::text[]) x LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'fm_app', r.tbl, 'fm_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'fm_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : share"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- JIT for the app role: checks are many small subplans, which JIT may spend longer compiling than running
  IF coalesce((SELECT split_part(c, '=', 2) FROM pg_db_role_setting s, unnest(s.setconfig) c
               WHERE s.setrole = v_role AND c LIKE 'jit=%'
                 AND s.setdatabase IN (0, (SELECT d.oid FROM pg_database d WHERE d.datname = current_database()))
               ORDER BY s.setdatabase DESC LIMIT 1), current_setting('jit')) IN ('on', 'true', '1') THEN
    severity := 'performance'; object := 'fm_app';
    problem := format('runs with JIT on: permission checks are many small subplans, and JIT can take longer to compile a read than to run it (a third of a second for a large one): ALTER ROLE %s SET jit = off', 'fm_app');
    RETURN NEXT;
  END IF;
  -- relations named like a type
  FOR r IN SELECT * FROM (VALUES ('membership', 'group', 'relation membership.group'), ('file', 'folder', 'relation file.folder'), ('version', 'file', 'relation version.file')) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), so in rules it reads like the type: a name that says what the relation is (author, member) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'));
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    IF has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"', '"fm"."users"', '"fm"."group_members"', '"fm"."groups"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') <> 'authzc masked view'
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'fm_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['fm.file_versions', 'fm.files', 'fm.folders', 'fm.group_members', 'fm.groups', 'fm.users', 'fm.group_members', 'fm.groups']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"fm"."group_members"', 'group_id', 'group.member: find the members of an object; group.admin: find the members of an object; membership.group: find objects by group_id'), ('"fm"."group_members"', 'user_id', 'group.member: find what a subject is in; group.admin: find what a subject is in; membership.person: find objects by user_id'), ('"fm"."groups"', 'parent_id', 'group.member: find the members of an object; group.parent: find objects by parent_id'), ('"fm"."groups"', 'id', 'group.member: find what a subject is in'), ('"fm"."groups"', 'owner_id', 'group.owner: find objects by owner_id'), ('"fm"."folders"', 'parent_id', 'folder.parent: find objects by parent_id'), ('"fm"."folders"', 'owner_id', 'folder.owner: find objects by owner_id'), ('"fm"."files"', 'folder_id', 'file.folder: find objects by folder_id'), ('"fm"."files"', 'owner_id', 'file.owner: find objects by owner_id'), ('"fm"."file_versions"', 'file_id', 'version.file: find objects by file_id')) v(tbl, col, why) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order)
    IF NOT EXISTS (SELECT 1 FROM pg_index i
                   WHERE i.indrelid = to_regclass(r.tbl)
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:cardinality(string_to_array(r.col, ', ')) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(r.col, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- Privileges the policy doesn't give on rowfence's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'fm_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'fm_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'fm_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'fm_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'fm_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowfence''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

